const { exec } = require('child_process');

return new Promise((resolve, reject) => {
  exec('scrot -s -c', (error, stdout, stderr) => {
    if (error) {
      resolve({ error: 'Gagal mengambil screenshot', stderr });
    } else {
      resolve({ message: 'Screenshot berhasil diambil', stdout });
    }
  });
});
